code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
    if not pts:
        return [row[:] for row in grid]

    # Choose the diagonal invariant that groups the painted streaks.
    scores = []
    for kind in (0, 1):  # 0: c-r (down-right), 1: r+c (down-left)
        groups = {}
        for r, c, _ in pts:
            k = c - r if kind == 0 else r + c
            groups[k] = groups.get(k, 0) + 1
        scores.append(sum(n * n for n in groups.values()))
    kind = 0 if scores[0] >= scores[1] else 1

    known = {}
    for r, c, v in pts:
        k = c - r if kind == 0 else r + c
        if k in known and known[k] != v:
            return [row[:] for row in grid]
        known[k] = v

    # The diagonal color word is periodic. Pick the shortest fully observed
    # period consistent with all painted diagonal stripes.
    period = None
    for p in range(1, max(known) - min(known) + 2):
        residues = {}
        ok = True
        for k, v in known.items():
            q = k % p
            if q in residues and residues[q] != v:
                ok = False
                break
            residues[q] = v
        if ok and len(residues) == p:
            period, word = p, residues
            break
    if period is None:
        # Robust fallback: use the smallest consistent period, then nearest
        # observed residue for any unseeded position.
        for p in range(1, max(known) - min(known) + 2):
            residues = {}
            ok = True
            for k, v in known.items():
                q = k % p
                if q in residues and residues[q] != v:
                    ok = False
                    break
                residues[q] = v
            if ok:
                period, word = p, residues
                break

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            k = c - r if kind == 0 else r + c
            q = k % period
            if q not in word:
                q = min(word, key=lambda x: min((x-q) % period, (q-x) % period))
            row.append(word[q])
        out.append(row)
    return out
